import Foundation

/// Embedded KaTeX JavaScript runtime and CSS stylesheet with embedded WOFF2 fonts.
/// Self-executing closures decode base64 data into static memory at runtime, ensuring
/// byte-for-byte fidelity without string interpolation corruption or missing font assets.
enum KaTeXAssets {
    static let jsString: String = {
        let b64 = ""
        guard let data = Data(base64Encoded: b64),
              let s = String(data: data, encoding: .utf8) else { return "" }
        return s
    }()

    static let cssString: String = {
        let b64 = ""
        guard let data = Data(base64Encoded: b64),
              let s = String(data: data, encoding: .utf8) else { return "" }
        return s
    }()
}
